    public function findTypeDataInjected(Query $query, array $options)
    {
        return $query->formatResults(function ($results){
            return $this->injectTypeData($results);
        });
    }

    public function injectTypeData(\Iterator $pages)
    {
        $index = [];
        $data = [];

        //fill the $index
        foreach($pages as $k => $page){
            $model = $page->type->model;
            $index[$model][$k] = $page->id;
        }
        //everything all right here, `_translations` property available

        //removed some stuff which fills $data array ($pages not manipulated)

        //put data to entity
        foreach($pages as $k => $page){
            $page->data = $data[$k];
        }
        //_translations property empty! already inside the foreach loop
        //groupTransations' trace: called after Collection::current(), which I think is called when iterating via foreach

        return $pages;        
    }
```

