    public function injectTypeData(\Iterator $pages)
    {
        $index = [];
        $data = [];

        //$pages->count() == 1

        //fill the $index
        foreach($pages as $k => $page){
            $model = $page->type->model;
            $index[$model][$k] = $page->id;
        }

        //removed some stuff which fills $data array ($pages not manipulated)

        debug(spl_object_hash($page)); //page from the last foreach iteration
        debug($page->get('_translations')); //OK :)

        $page = $pages->first();
        debug(spl_object_hash($page));
        debug($pages->get('_translations')); //empty :(

        //put data to entity
        foreach($pages as $k => $page){
            $page->data = $data[$k];
        }

        return $pages;        
    }
```

_note: spl_object_hash() returns the same value for both_
